parts.text:
{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Introduces statutory definitions that apply throughout the chapter, establishing no independent operational duties or legal rules on its own."
    },
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Serves as the subparagraph heading for 'Individualized education program' and contains no substantive legal command or rule."
    },
    {
      "quote_ref": "F002",
      "scope_refs": ["F000"],
      "kind": "definition",
      "meaning": "Under this chapter, the term 'individualized education program' or 'IEP' is defined as a written statement for each child with a disability that is developed, reviewed, and revised in accordance with 20 U.S.C. 1414 and that includes the specified components set forth in subclauses (I) through (VIII)."
    },
    {
      "quote_ref": "F003",
      "scope_refs": ["F000", "F002"],
      "kind": "requirement",
      "meaning": "An IEP must include a statement of the child's present levels of academic achievement and functional performance, including the specific elements described in items (aa) through (cc)."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F000", "F002", "F003"],
      "kind": "requirement",
      "meaning": "As part of the IEP statement of present levels of academic achievement and functional performance, the IEP must include how the child's disability affects the child's involvement and progress in the general education curriculum."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F000", "F002", "F003"],
      "kind": "requirement",
      "meaning": "As part of the IEP statement of present levels of academic achievement and functional performance, the IEP must include, for preschool children as appropriate, how the disability affects the child's participation in appropriate activities."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F000", "F002", "F003"],
      "kind": "requirement",
      "meaning": "For children with disabilities who take alternate assessments aligned to alternate achievement standards, the IEP statement of present levels of achievement and performance must include a description of benchmarks or short-term objectives."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F000", "F002"],
      "kind": "requirement",
      "meaning": "An IEP must include a statement of measurable annual goals, including academic and functional goals, designed to meet the disability-related needs of the child."
    },
    {
      "quote_ref": "F008",
      "scope_refs": ["F000", "F002", "F007"],
      "kind": "requirement",
      "meaning": "The measurable annual goals in an IEP must be designed to meet the child's needs resulting from the disability to enable the child to be involved in and make progress in the general education curriculum."
    },
    {
      "quote_ref": "F009",
      "scope_refs": ["F000", "F002", "F007"],
      "kind": "requirement",
      "meaning": "The measurable annual goals in an IEP must be designed to meet each of the child's other educational needs that result from the child's disability."
    },
    {
      "quote_ref": "F010",
      "scope_refs": ["F000", "F002", "F007"],
      "kind": "requirement",
      "meaning": "An IEP must include a description of how the child's progress toward meeting the measurable annual goals will be measured and when periodic reports on the child's progress (such as quarterly or other periodic reports concurrent with report cards) will be provided."
    },
    {
      "quote_ref": "F011",
      "scope_refs": ["F000", "F002"],
      "kind": "requirement",
      "meaning": "An IEP must include a statement of the special education and related services and supplementary aids and services (based on peer-reviewed research to the extent practicable) to be provided to or on behalf of the child, and a statement of the program modifications or supports for school personnel that will be provided for the child."
    },
    {
      "quote_ref": "F012",
      "scope_refs": ["F000", "F002", "F011"],
      "kind": "requirement",
      "meaning": "The special education, related services, supplementary aids, program modifications, and personnel supports in the IEP must be provided for the child to advance appropriately toward attaining the annual goals."
    },
    {
      "quote_ref": "F013",
      "scope_refs": ["F000", "F002", "F011"],
      "kind": "requirement",
      "meaning": "The special education, related services, supplementary aids, program modifications, and personnel supports in the IEP must be provided for the child to be involved in and make progress in the general education curriculum in accordance with subclause (I) and to participate in extracurricular and other nonacademic activities."
    },
    {
      "quote_ref": "F014",
      "scope_refs": ["F000", "F002", "F011"],
      "kind": "requirement",
      "meaning": "The special education, related services, supplementary aids, program modifications, and personnel supports in the IEP must be provided for the child to be educated and participate with other children with disabilities and nondisabled children in the activities described in subparagraph (A)."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F000", "F002", "F011", "F014"],
      "kind": "requirement",
      "meaning": "An IEP must include an explanation of the extent, if any, to which the child will not participate with nondisabled children in the regular class and in extracurricular, nonacademic, and educational activities described in subclause (IV)(cc)."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Serves as a structural subclause marker for subclause (VI) without substantive legal content on its own."
    },
    {
      "quote_ref": "F017",
      "scope_refs": ["F000", "F002"],
      "kind": "requirement",
      "meaning": "An IEP must include a statement of any individual appropriate accommodations necessary to measure the academic achievement and functional performance of the child on State and districtwide assessments consistent with 20 U.S.C. 1412(a)(16)(A)."
    },
    {
      "quote_ref": "F018",
      "scope_refs": ["F000", "F002"],
      "kind": "condition",
      "meaning": "If the IEP Team determines that the child shall take an alternate assessment on a particular State or districtwide assessment of student achievement, the IEP must include a statement explaining why the child cannot participate in the regular assessment and why the alternate assessment is appropriate."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F000", "F002", "F018"],
      "kind": "requirement",
      "meaning": "When an alternate assessment is determined for the child by the IEP Team, the IEP statement must explain why the child cannot participate in the regular assessment."
    },
    {
      "quote_ref": "F020",
      "scope_refs": ["F000", "F002", "F018"],
      "kind": "requirement",
      "meaning": "When an alternate assessment is determined for the child by the IEP Team, the IEP statement must explain why the particular alternate assessment selected is appropriate for the child."
    },
    {
      "quote_ref": "F022",
      "scope_refs": ["F000", "F002", "F011"],
      "kind": "requirement",
      "meaning": "An IEP must state the projected date for the beginning of the services and modifications described in subclause (IV), as well as their anticipated frequency, location, and duration."
    },
    {
      "quote_ref": "F023",
      "scope_refs": ["F000", "F002"],
      "kind": "threshold",
      "meaning": "The transition-related IEP requirements of subclause (VIII) must be included beginning not later than the first IEP to be in effect when the child is 16, and must be updated annually thereafter."
    },
    {
      "quote_ref": "F024",
      "scope_refs": ["F000", "F002", "F023"],
      "kind": "requirement",
      "meaning": "Beginning not later than the first IEP in effect when the child is 16 (and updated annually), the IEP must include appropriate measurable postsecondary goals based upon age-appropriate transition assessments related to training, education, employment, and, where appropriate, independent living skills."
    },
    {
      "quote_ref": "F025",
      "scope_refs": ["F000", "F002", "F023", "F024"],
      "kind": "requirement",
      "meaning": "Beginning not later than the first IEP in effect when the child is 16 (and updated annually), the IEP must include the transition services (including courses of study) needed to assist the child in reaching the specified postsecondary goals."
    },
    {
      "quote_ref": "F026",
      "scope_refs": ["F000", "F002", "F023"],
      "kind": "requirement",
      "meaning": "Beginning not later than 1 year before the child reaches the age of majority under State law, the IEP must include a statement that the child has been informed of the child's rights under this chapter, if any, that will transfer to the child on reaching the age of majority under 20 U.S.C. 1415(m)."
    },
    {
      "quote_ref": "F028",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "Nothing in 20 U.S.C. 1414 shall be construed to require the specific additional inclusions identified in subclauses (I) and (II)."
    },
    {
      "quote_ref": "F029",
      "scope_refs": ["F028"],
      "kind": "statement",
      "meaning": "Nothing in 20 U.S.C. 1414 requires additional information to be included in a child's IEP beyond what is explicitly required in this section."
    },
    {
      "quote_ref": "F030",
      "scope_refs": ["F028"],
      "kind": "statement",
      "meaning": "Nothing in 20 U.S.C. 1414 requires the IEP Team to include information under one component of a child's IEP that is already contained under another component of that IEP."
    },
    {
      "quote_ref": "F032",
      "scope_refs": ["F000"],
      "kind": "definition",
      "meaning": "The term 'individualized education program team' or 'IEP Team' is defined as a group of individuals composed of the members enumerated in clauses (i) through (vii)."
    },
    {
      "quote_ref": "F033",
      "scope_refs": ["F000", "F032"],
      "kind": "requirement",
      "meaning": "The IEP Team must include the parents of the child with a disability."
    },
    {
      "quote_ref": "F034",
      "scope_refs": ["F000", "F032"],
      "kind": "requirement",
      "meaning": "The IEP Team must include not less than 1 regular education teacher of the child, if the child is, or may be, participating in the regular education environment."
    },
    {
      "quote_ref": "F035",
      "scope_refs": ["F000", "F032"],
      "kind": "requirement",
      "meaning": "The IEP Team must include not less than 1 special education teacher of the child, or where appropriate, not less than 1 special education provider of the child."
    },
    {
      "quote_ref": "F036",
      "scope_refs": ["F000", "F032"],
      "kind": "requirement",
      "meaning": "The IEP Team must include a representative of the local educational agency who meets the qualifications described in subclauses (I), (II), and (III)."
    },
    {
      "quote_ref": "F037",
      "scope_refs": ["F000", "F032", "F036"],
      "kind": "requirement",
      "meaning": "The local educational agency representative on the IEP Team must be qualified to provide, or supervise the provision of, specially designed instruction to meet the unique needs of children with disabilities."
    },
    {
      "quote_ref": "F038",
      "scope_refs": ["F000", "F032", "F036"],
      "kind": "requirement",
      "meaning": "The local educational agency representative on the IEP Team must be knowledgeable about the general education curriculum."
    },
    {
      "quote_ref": "F039",
      "scope_refs": ["F000", "F032", "F036"],
      "kind": "requirement",
      "meaning": "The local educational agency representative on the IEP Team must be knowledgeable about the availability of resources of the local educational agency."
    },
    {
      "quote_ref": "F041",
      "scope_refs": ["F000", "F032"],
      "kind": "requirement",
      "meaning": "The IEP Team must include an individual who can interpret the instructional implications of evaluation results, who may also be a member described in clauses (ii) through (vi)."
    },
    {
      "quote_ref": "F042",
      "scope_refs": ["F000", "F032"],
      "kind": "permission",
      "meaning": "At the discretion of the parent or the agency, the IEP Team may include other individuals who have knowledge or special expertise regarding the child, including related services personnel as appropriate."
    },
    {
      "quote_ref": "F043",
      "scope_refs": ["F000", "F032"],
      "kind": "requirement",
      "meaning": "Whenever appropriate, the child with a disability must be included as a member of the IEP Team."
    },
    {
      "quote_ref": "F044",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Serves as the subparagraph heading for 'IEP Team attendance' and contains no operational rules."
    },
    {
      "quote_ref": "F045",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Serves as the clause heading for 'Attendance not necessary' and contains no independent substantive rule."
    },
    {
      "quote_ref": "F046",
      "scope_refs": [],
      "kind": "exemption",
      "meaning": "A member of the IEP Team is not required to attend an IEP meeting, in whole or in part, if the parent of a child with a disability and the local educational agency agree that the attendance is not necessary because the member's area of the curriculum or related services is not being modified or discussed in the meeting."
    },
    {
      "quote_ref": "F048",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "A member of the IEP Team may be excused from attending an IEP meeting, in whole or in part, when the meeting involves a modification to or discussion of the member's area of curriculum or related services, provided that the conditions of subclauses (I) and (II) are satisfied."
    },
    {
      "quote_ref": "F049",
      "scope_refs": ["F048"],
      "kind": "condition",
      "meaning": "To excuse an IEP Team member when their area is modified or discussed, the parent and the local educational agency must consent to the excusal."
    },
    {
      "quote_ref": "F050",
      "scope_refs": ["F048"],
      "kind": "condition",
      "meaning": "To excuse an IEP Team member when their area is modified or discussed, the member must submit, in writing to the parent and the IEP Team, input into the development of the IEP prior to the meeting."
    },
    {
      "quote_ref": "F052",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Serves as the clause heading for 'Written agreement and consent required' and contains no independent legal rule."
    },
    {
      "quote_ref": "F053",
      "scope_refs": ["F046", "F048", "F049"],
      "kind": "requirement",
      "meaning": "A parent's agreement that an IEP Team member's attendance is not necessary under clause (i) and a parent's consent to excusal under clause (ii) must be in writing."
    },
    {
      "quote_ref": "F055",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Serves as the subparagraph heading for 'IEP Team transition' and contains no substantive legal content."
    },
    {
      "quote_ref": "F056",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "In the case of a child previously served under subchapter III, an invitation to the initial IEP meeting must, at the request of the parent, be sent to the subchapter III service coordinator or other representatives of the subchapter III system to assist with the smooth transition of services."
    }
  ]
}
